        total = 0
        for i in range(len(seq)):
            total += seq[i]
            if total % n == 0:
                return False
        return True

    def generate_sequences(prefix, length, current_sum):
        if length == 0:
            if not is_valid_sequence(prefix):
                return [prefix]
            return []
        sequences = []
        for petals in range(1, n):
            if current_sum + petals >= n * (length - 1):
                break
            sequences.extend(generate_sequences(prefix + [petals], length - 1, current_sum + petals))
        return sequences

    total_sequences = 0
    prefix = []

    # Generate valid sequences until we reach the k-th one
    for initial_petals in range(1, n):
        valid_sequences = generate_sequences(prefix + [initial_petals], n - 1, initial_petals)
        total_sequences += len(valid_sequences)
        if total_sequences >= k:
            # Find the exact k-th sequence in this range
            return valid_sequences[k - total_sequences + len(valid_sequences) - 1]

