def kth_sequence(n, k):
    # Initialize an empty sequence
    sequence = []

    # Calculate the number of valid sequences
    def count_valid_sequences(sequence, index, total_petals):
        if index == n - 1:
            return 1 if total_petals % n != 0 else 0

        count = 0
        for petals in range(1, n):
            if (total_petals + petals) % n != 0:
                count += count_valid_sequences(sequence + [petals], index + 1, total_petals + petals)
        return count

    # Generate the k-th sequence
    def generate_sequence(sequence, index, total_petals, k):
        if index == n - 1:
            return sequence

        for petals in range(1, n):
            if (total_petals + petals) % n == 0:
                continue

            # Count sequences starting with this number
            next_sequence = sequence + [petals]
            count = count_valid_sequences(next_sequence, index + 1, total_petals + petals)

            if k <= count:
                return generate_sequence(next_sequence, index + 1, total_petals + petals, k)
            else:
                k -= count

    return generate_sequence([], 0, 0, k)

